import{c as a,Q as r,j as i,m as n}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Learning and Reusing Policy Decompositions for Hierarchical Generalized Planning with LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.06957","title":"Learning and Reusing Policy Decompositions for Hierarchical Generalized Planning with LLM Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2605.06957,"authors":["Shirin Sohrabi","Haritha Ananthakrishnan","Harsha Kokel","Kavitha Srinivas","Michael Katz"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2605.06957v1","pdf_path":"pdfs/2605.06957.pdf","published_date":"2026-05-07T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-07-policy-decompositions-hierarchical-generalized-planning-2605-06957.md","filePath":"research/papers/2026-05-07-policy-decompositions-hierarchical-generalized-planning-2605-06957.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-05-07-policy-decompositions-hierarchical-generalized-planning-2605-06957.md"};function t(s,e,l,c,h,p){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="learning-and-reusing-policy-decompositions-for-hierarchical-generalized-planning-with-llm-agents" tabindex="-1">Learning and Reusing Policy Decompositions for Hierarchical Generalized Planning with LLM Agents <a class="header-anchor" href="#learning-and-reusing-policy-decompositions-for-hierarchical-generalized-planning-with-llm-agents" aria-label="Permalink to &quot;Learning and Reusing Policy Decompositions for Hierarchical Generalized Planning with LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Shirin Sohrabi, Haritha Ananthakrishnan, Harsha Kokel, Kavitha Srinivas, Michael Katz <strong>Published</strong>: May 7, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.06957" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.06957</a> · <a href="https://arxiv.org/html/2605.06957v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2605.06957 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.06957" target="_blank" rel="noreferrer">research/papers/pdfs/2605.06957.pdf</a> (17 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>We present a dynamic policy-learning approach that combines generalized planning and hierarchical task decomposition for LLM-based agents. Our method, Hierarchical Component Learning for Generalized Policies (HCL-GP ), learns parameterized policies that generalize across task instances and automatically extracts reusable components from successful executions, organizing them into a component library for compositional policy generation. We address three challenges: (1) learning components through automated decomposition, (2) generalizing components to maximize reuse, and (3) efficient retrieval via semantic search. Evaluated on the AppWorld benchmark, our approach achieves 98.2% accuracy on normal tasks and 97.8% on challenge tasks with unseen applications, improving 15.8 points over static synthesis on challenging scenarios. For open-source models, dynamic reuse enables 62.5% success versus near-zero without reuse. This demonstrates that classical planning concepts can be effectively integrated with LLM agents for improved accuracy and efficiency.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>HCL-GP</strong>（Hierarchical Component Learning for Generalized Policies）：結合 generalized planning 與 hierarchical task decomposition 的 dynamic policy-learning 方法，服務 LLM-based agents。</li><li>學習 <strong>parameterized policies</strong>，使其能跨 task instances 泛化，而非綁定單一任務。</li><li>從成功執行軌跡中<strong>自動抽取可重用 component</strong>，組織成 component library，支援 compositional policy generation。</li><li>三個明確子問題：(1) 透過 automated decomposition 學 component；(2) 泛化 component 以最大化 reuse；(3) 以 semantic search 做高效 retrieval。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li><strong>AppWorld benchmark</strong>：normal tasks 達 98.2% accuracy；challenge tasks（含 unseen applications）達 97.8%。</li><li>在 challenging scenarios 上比 static synthesis <strong>提升 15.8 個百分點</strong>。</li><li><strong>Open-source models</strong>：啟用 dynamic reuse 後成功率 62.5%，相對於「無 reuse」近乎 0% 的成績為決定性差距。</li><li>結論層級主張：classical planning 概念可有效整合進 LLM agents，同時改善 accuracy 與 efficiency。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件未列明確 limitation 章節（依 abstract 判讀）。可推測弱點：</p><ul><li>評估僅限單一 benchmark（AppWorld），跨領域泛化未驗證。</li><li>component library 隨任務累積可能膨脹，semantic retrieval 的 precision/latency 在大 library 下的 scaling 未由 abstract 佐證。</li><li>open-source 模型「near-zero without reuse」暗示方法對 base model 能力高度敏感，reuse 機制是否掩蓋了底層 reasoning 不足值得審視。</li><li>「automated decomposition」品質依賴成功軌跡，cold-start（無歷史成功）情境的表現未述。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>Policy decompositions ↔ The Loop 子目標分解</strong>：HCL-GP 的 automated decomposition + component library 與 workspace「任務拆 ≥3 獨立子任務 → fan-out」的委派決策同構；可作為「子目標如何被機械抽取與重用」的外部參考框架。⚠️ 落地門檻：本文針對 AppWorld API-agent，與本 workspace 的 sub-agent handoff contract 無現成對應實作。</li><li><strong>Component reuse ↔ Rule of 3 抽象紀律</strong>：論文「generalize components to maximize reuse」與 core.md「≥3 呼叫點才抽 helper」呼應，但方向相反——論文鼓勵積極泛化重用，workspace 刻意抑制投機抽象。⚠️ 兩者目標函式不同（agent 任務成功率 vs codebase 可維護性），不可直接套用。</li><li><strong>Semantic retrieval ↔ MEMORY/LESSONS 注入</strong>：component library 的 semantic search 檢索機制，概念上類比 workspace 的長期記憶回路（MEMORY.md / LESSONS.md session 注入）。⚠️ 本文是 runtime policy retrieval，workspace memory 是 session-start 靜態注入，retrieval 觸發時機與粒度不同。</li><li><strong>generalized planning ↔ pilot/effort 路由</strong>：「classical planning 整合 LLM」的論點，與 workspace「確定性代碼做決定、LLM 做判斷」的跨切紀律方向一致（用結構化 planning 約束 LLM 自由度）。⚠️ 僅為理念層共鳴，無程式碼或設定可直接借用。</li></ul>',17)])])}const m=a(o,[["render",t]]);export{g as __pageData,m as default};
